import Foundation
import Darwin

/// Sensitive per-device enrollment generated by the Mac gateway.
/// Transfer only over local AirDrop/USB; never print or place in a QR code.
struct IKEv2Enrollment: Decodable {
    static let maximumPayloadBytes = 64 * 1024

    let version: Int
    let deviceName: String
    let serverAddress: String
    let serverIdentifier: String
    let username: String
    let password: String

    static func decode(_ data: Data) throws -> IKEv2Enrollment {
        guard data.count <= maximumPayloadBytes else {
            throw EnrollmentError.invalidConfiguration
        }
        let value = try JSONDecoder().decode(IKEv2Enrollment.self, from: data)
        guard value.version == 1,
              !value.deviceName.isEmpty, value.deviceName.count <= 32,
              Self.validHost(value.serverAddress), Self.validHost(value.serverIdentifier),
              !value.username.isEmpty, value.username.count <= 128,
              !value.password.isEmpty, value.password.count <= 256 else {
            throw EnrollmentError.invalidConfiguration
        }
        return value
    }

    private static func validHost(_ value: String) -> Bool {
        guard !value.isEmpty, value.count <= 253,
              value.rangeOfCharacter(from: .whitespacesAndNewlines) == nil else { return false }
        if value.contains(":") {
            var address = in6_addr()
            return value.withCString { inet_pton(AF_INET6, $0, &address) == 1 }
        }
        if value.contains(".") && value.allSatisfy({ $0.isNumber || $0 == "." }) {
            var address = in_addr()
            return value.withCString { inet_pton(AF_INET, $0, &address) == 1 }
        }
        return value.split(separator: ".", omittingEmptySubsequences: false).allSatisfy { label in
            let bytes = Array(label.utf8)
            guard !bytes.isEmpty, bytes.count <= 63,
                  let first = bytes.first, let last = bytes.last,
                  isAsciiAlphaNumeric(first), isAsciiAlphaNumeric(last) else { return false }
            return bytes.allSatisfy { isAsciiAlphaNumeric($0) || $0 == 45 }
        }
    }

    private static func isAsciiAlphaNumeric(_ byte: UInt8) -> Bool {
        (byte >= 48 && byte <= 57) || (byte >= 65 && byte <= 90)
            || (byte >= 97 && byte <= 122)
    }
}

enum EnrollmentError: LocalizedError {
    case invalidConfiguration
    var errorDescription: String? {
        "配置文件无效或字段不完整。请从 Mac 重新生成该设备的 IKEv2 App 配置。"
    }
}
